// A Map (hidden class) is identified by the ORDERED construction path.
function mapSig(o) {
  // sort the keys to make the signature stable
  return Object.keys(o).sort().join(',');
}
function countDistinct(objs) {
  const seen = new Set();
  for (const o of objs) seen.add(mapSig(o));
  return seen.size;
}

